55	            throws InvalidPoolException {
56	        if (request == null || request.pool() == null || !pools.has(sheet, request.pool())) {
57	            throw new InvalidPoolException("No such pool");
58	        }
59	        String sub = request.memberPool() == null ? null : request.memberPool().trim();
60	        Person person = sub != null || request.person() == null ? null : people.find(sheet, request.person());
61	        if (sub != null ? !pools.has(sheet, sub) : person == null) {
62	            throw new InvalidPoolException("Choose a person or a pool");
63	        }
64	        String raw = request.share() == null ? "" : request.share().trim();
65	        if (!SHARE.matcher(raw).matches()) {
66	            throw new InvalidPoolException("A share is a percent with at most two decimals");
67	        }
68	        BigDecimal share = new BigDecimal(raw).setScale(2);
69	        if (share.signum() <= 0 || share.compareTo(FULL) > 0) {
70	            throw new InvalidPoolException("A share must be more than 0.00 and at most 100.00");
71	        }
72	        LocalDate from = date(request.from());
73	        LocalDate to = date(request.to());
74	        if (from != null && to != null && to.isBefore(from)) {
75	            throw new InvalidPoolException("A membership may not end before it starts");
76	        }
77	        String dates = (from == null ? "" : " from=" + from) + (to == null ? "" : " to=" + to);
78	        if (sub != null) {
79	            checkSubPool(sheet, request.pool(), sub, pools);
80	            pools.addSubPool(sheet, request.pool(), sub, share, from, to);
81	            audit.record("POOL_MEMBER_ADDED sheet=" + sheet + " by=" + user + " pool=" + request.pool() + " name="
82	                    + sub + " share=" + share.toPlainString() + dates);
83	            return;
