86	            throw new InvalidPoolException(person.name() + " is already in " + request.pool());
87	        }
88	        pools.addMember(sheet, request.pool(), person.id(), share, from, to);
89	        audit.record("POOL_MEMBER_ADDED sheet=" + sheet + " by=" + user + " pool=" + request.pool() + " name="
90	                + person.name() + " share=" + share.toPlainString() + dates);
91	    }
