93	    /** The date given, or null when blank. */
94	    private static LocalDate date(String raw) throws InvalidPoolException {
95	        String date = raw == null ? "" : raw.trim();
96	        if (date.isEmpty()) {
97	            return null;
98	        }
99	        try {
100	            return LocalDate.parse(date);
101	        } catch (DateTimeParseException e) {
102	            throw new InvalidPoolException("Not a valid date: " + date);
