106	    /** Refuses a pool already in a pool, one that would contain itself, or a chain more than three deep. */
107	    private static void checkSubPool(String sheet, String pool, String sub, Pools pools) throws InvalidPoolException {
108	        if (pools.parentOf(sheet, sub) != null) {
109	            throw new InvalidPoolException(sub + " is already a member of a pool");
110	        }
111	        int above = 0;
112	        for (String p = pool; p != null; p = pools.parentOf(sheet, p)) {
113	            if (p.equals(sub)) {
114	                throw new InvalidPoolException(pool + " cannot contain itself");
115	            }
116	            above++;
117	        }
118	        if (above + depth(sheet, sub, pools) > MAX_DEPTH) {
119	            throw new InvalidPoolException("A chain of pools is at most " + MAX_DEPTH + " deep");
120	        }
121	    }
122	
123	    /** How many pools deep the chain below and including this pool goes. */
124	    private static int depth(String sheet, String pool, Pools pools) {
125	        int below = 0;
126	        for (String sub : pools.subPools(sheet, pool)) {
127	            below = Math.max(below, depth(sheet, sub, pools));
128	        }
129	        return below + 1;
130	    }
