314	    private static Pool cutDown(String name, Map<String, Pool> pools, Map<String, String> parents, BigDecimal sheetPot,
315	            Set<Long> held, Map<String, Pool> done) {
316	        Pool known = done.get(name);
317	        if (known != null) {
318	            return known;
319	        }
320	        Pool pool = pools.get(name);
321	        BigDecimal pot = sheetPot;
322	        String parent = parents.get(name);
323	        if (parent != null && pools.containsKey(parent)) {
324	            pot = null;
325	            for (PoolMember m : cutDown(parent, pools, parents, sheetPot, held, done).members()) {
326	                if (name.equals(m.memberPool()) && !m.cut().isEmpty()) {
327	                    pot = new BigDecimal(m.cut());
328	                }
329	            }
330	        }
331	        Pool out = pool.balanced() && pot != null
