338	    /**
339	     * The members each with their cut of the pot: the pot times their share over the shares of the members with a cut
340	     * (neither retired nor held), half to even to two decimals (a retired or held member's 0.00); the remainder, the
341	     * pot less the cuts, goes to the member with the smallest non-zero cut, the latest added on a tie (or, when no
342	     * cut is non-zero, to the last member with a cut and a share), so the cuts total the pot (each 0.00 when no member has a cut). A pool whose every member within their dates is retired
343	     * shows no cuts.
344	     */
345	    private static List<PoolMember> cut(List<PoolMember> members, BigDecimal pot, Set<Long> held) {
346	        if (members.stream().filter(PoolMember::current).allMatch(PoolMember::retired)) {
347	            return members;
348	        }
349	        BigDecimal shares = BigDecimal.ZERO.setScale(2);
350	        for (PoolMember m : members) {
351	            if (hasCut(m, held)) {
352	                shares = shares.add(new BigDecimal(m.share()));
353	            }
354	        }
355	        List<BigDecimal> cuts = new ArrayList<>();
356	        BigDecimal sum = BigDecimal.ZERO.setScale(2);
357	        for (PoolMember m : members) {
358	            BigDecimal cut = hasCut(m, held) && shares.signum() > 0
359	                    ? pot.multiply(new BigDecimal(m.share())).divide(shares, 2, RoundingMode.HALF_EVEN)
360	                    : BigDecimal.ZERO.setScale(2);
361	            cuts.add(cut);
362	            sum = sum.add(cut);
363	        }
364	        int smallest = -1;
365	        int lastShare = -1;
366	        for (int i = 0; i < members.size(); i++) {
367	            if (!hasCut(members.get(i), held)) {
368	                continue;
369	            }
370	            if (new BigDecimal(members.get(i).share()).signum() > 0) {
371	                lastShare = i;
372	            }
373	            BigDecimal cut = cuts.get(i);
374	            if (cut.signum() != 0 && (smallest < 0 || cut.compareTo(cuts.get(smallest)) <= 0)) {
375	                smallest = i;
376	            }
377	        }
378	        int takes = smallest >= 0 ? smallest : lastShare;
379	        if (takes >= 0 && shares.signum() > 0) {
380	            cuts.set(takes, cuts.get(takes).add(pot.subtract(sum)));
381	        }
382	        List<PoolMember> out = new ArrayList<>();
383	        for (int i = 0; i < members.size(); i++) {
384	            PoolMember m = members.get(i);
385	            out.add(new PoolMember(m.person(), m.memberPool(), m.name(), m.share(), m.retired(), m.from(), m.to(),
386	                    m.current(), m.current() ? cuts.get(i).toPlainString() : ""));
387	        }
388	        return out;
389	    }
